INSERT INTO public.experience (id, title, company, location, type, start_date, end_date, description, responsibilities, technologies, achievements, company_url, sort_order, created_at, updated_at) VALUES ('isrc-ninja-combined', 'Full Stack Engineer / Tech Lead', 'Intensive Study and Research Center (ISRC), later Ninja Infosys', 'Kathmandu, Nepal', 'job', '2024-01', '2026-02', 'Drove large-scale digital transformation across Nepal''s municipal governance ecosystem — from building survey and digital profile infrastructure for 10+ municipalities, to leading architecture for platforms serving 50+ municipalities and 100+ government websites.', '{"Deployed digital profile systems for 10+ municipalities including Pokhara Metropolitan City in 4 months with a 2-person team, serving 100,000+ citizens","Built a Survey Management System with custom ODK Fetcher processing 100,000+ survey responses with real-time analytics and live monitoring","Managed end-to-end DevOps pipelines (CI/CD, Docker, AWS EC2/S3, MinIO, Jenkins) ensuring 99.9% uptime for resource-constrained regions","Trained 300+ local officials and enumerators in digital tools for sustainable civic digitization"}', '{Next.js,NestJS,tRPC,PostgreSQL,MongoDB,Docker,AWS,MinIO,"ODK Collect/Central",Nginx}', '{"10+ municipal digital profiles deployed in 4 months with a 2-person team","100,000+ survey responses processed with real-time analytics","300+ local officials trained in digital tools"}', NULL, 0, '2026-08-16 12:22:04.126635+05:30', '2026-08-16 12:22:04.126635+05:30') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.experience (id, title, company, location, type, start_date, end_date, description, responsibilities, technologies, achievements, company_url, sort_order, created_at, updated_at) VALUES ('mandala-foods-consultant', 'AI & Automation Consultant', 'Mandala Foods', 'Remote, Nepal', 'job', '2026-01', NULL, 'Sole technical architect for a purpose-driven fruit upcycling startup, building AI and automation infrastructure from the ground up. Designed conversational AI systems and self-hosted production infrastructure to streamline operations and enable intelligent commerce.', '{"Designed and deployed Maya — an internal RAG-based knowledge chatbot for querying SOPs and operational documentation through natural language","Architected Maya Genie, a multi-channel conversational commerce platform (WhatsApp, Viber, Messenger) with a Go-based message orchestration gateway, LangChain RAG core, and Nepal payment integrations (Khalti, eSewa)","Built a public-facing product chatbot on a loosely coupled microservices architecture with independently deployable channels, orchestration, and cognitive core","Engineered a Go document sync service processing Vikunja task attachments (XLSX, CSV, DOCX) and auto-uploading to Google Drive to feed the n8n RAG embedding pipeline","Self-hosted and maintained a production VPS (Ubuntu 24.04, 12-core AMD EPYC, 48 GB RAM) running 10+ Dockerised services including n8n, Supabase, Traefik, Open WebUI, and a Claude API proxy","Built n8n automation workflows for document ingestion, Gemini-powered embedding pipelines, operational reporting, and industry news digests"}', '{Go,Python,LangChain,n8n,Docker,"Supabase (pgvector)","Anthropic Claude API",Redis,"RAG Architecture",Microservices,Traefik,"Open WebUI"}', '{"Maya Genie submitted to the AI by HER: Global Impact Challenge","10+ Dockerised production services self-hosted on a single VPS with full observability","Multi-channel commerce platform spanning WhatsApp, Viber, and Messenger"}', NULL, 0, '2026-08-16 12:22:04.725912+05:30', '2026-08-16 12:22:04.725912+05:30') ON CONFLICT (id) DO NOTHING;

